import time
import jwt  # PyJWT

JWKS_KEY = "<cached-public-key>"  # fetched via JWKS, cached 10 min
AUDIENCE = "orders-api"
ISSUER = "https://auth.example.internal/"
LEEWAY_S = 60

def authenticate(headers):
    # Gate 1: AuthN — who is this? No policy here.
    token = headers.get("Authorization", "").removeprefix("Bearer ").strip()
    if not token:
        raise Unauthorized("missing token")
    try:
        claims = jwt.decode(token, JWKS_KEY, algorithms=["RS256"],
                            audience=AUDIENCE, issuer=ISSUER, leeway=LEEWAY_S)
    except jwt.ExpiredSignatureError:
        raise Unauthorized("expired")
    except jwt.InvalidTokenError as e:
        raise Unauthorized(f"invalid: {e}")
    return {"sub": claims["sub"], "tid": claims["tid"],
            "scp": set(claims.get("scp", []))}

def authorize(ctx, action, resource):
    # Gate 2: AuthZ — can they do this? No crypto here.
    if action == "order:read":
        if "orders:read" not in ctx["scp"]:
            raise Forbidden("missing scope")
        # Ownership check must use DB, with tid from token only:
        order = db.get_order(resource["order_id"])  # indexed (id, tenant_id)
        if order is None or order.tenant_id != ctx["tid"]:
            raise Forbidden("not your tenant")  # do not return 404 vs 403 oracle
        return order
    raise Forbidden("unknown action")
